@Test public void widevineOfflineReleasedLicenseV29() throws Throwable {
  if (Util.SDK_INT < 29 || GtsTestUtil.shouldSkipWidevineTest(testRule.getActivity())) {
    return;
  }
  try {
    downloadLicense();
    releaseLicense();
  } catch (IllegalArgumentException e) {
    fail("Unexpected IllegalArgumentException: " + e.getMessage());
  }
  Throwable error=assertThrows("Playback should fail because the license has been released.",Throwable.class,() -> testRunner.run());
  Throwable cause=error.getCause();
  while (cause != null && cause != error) {
    error=cause;
    cause=error.getCause();
  }
  assertThat(error).isInstanceOf(IllegalArgumentException.class);
}
